UPDATE services SET summary = 'New enquiries every day — from people who actually want to buy. Every lead tracked.', intro = 'A complete lead system for your business: a focused landing page, an offer people can’t refuse, visitors from ads or Google, and WhatsApp follow-up — so no enquiry slips away.' WHERE slug = 'lead-generation';
UPDATE services SET summary = '24/7 auto-replies, menus and bookings — never miss a customer again.', intro = 'Our customers prefer WhatsApp over forms or email. Smart menus, instant replies and bookings on your WhatsApp Business number — leads keep coming in even while you sleep.' WHERE slug = 'whatsapp';
UPDATE services SET summary = 'Opens in a blink on mobile, and takes visitors straight to a call or WhatsApp.', intro = 'Clean, mobile-first websites and simple web apps — they load in 1.5 seconds, rank on Google, and guide every visitor towards a call or WhatsApp.' WHERE slug = 'web-dev';
